arguments.command:
node --input-type=module -e "
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { GLB } from './js/glb.mjs';
import { Game } from './js/game.mjs';
function loadGlb(n){const g=new GLB(n);g.raw=new Uint8Array(readFileSync(path.resolve('data',n)));return g.parse();}
const glb1=loadGlb('FILE0001.GLB'), glb0=loadGlb('FILE0000.GLB');
const game=new Game(glb1,glb0,{play(){},sfxCount:0,state:'running'});
const r={ready:false,player:{x:0,y:0,alive:false},projectiles:[],enemies:[],hud:{score:0,shields:0},audio:{contextState:'suspended',sfxCount:0},wave:0,sectorComplete:false};
game.frame();
game.syncRaptor(r);
// 1) ready flipped by the first drawn frame
console.log('ready:', r.ready, '| wave:', r.wave, '| player:', JSON.stringify(r.player));
// 2) background: sample tiles across the playfield for palette-index variance
const px=game.px;
let nonblack=0, distinct=new Set();
for (let i=0;i<320*200;i++){ if (px[i]!==0) nonblack++; distinct.add(px[i]); }
console.log('non-black px:', nonblack, '| palette entries used:', distinct.size);
// 3) ship: ship pic center should differ from a blank-background render.
//    Player at (148..172, 156..180) approx; sample a horizontal slice through it.
let shipPx=0;
for (let y=156;y<180;y+=2) for (let x=148;x<172;x+=2) { if (px[y*320+x]!==0) shipPx++; }
console.log('non-black px in ship region:', shipPx, '(>0 means ship pixels present)');
// 4) tiles came from MAP1G1_MAP item (real GLB data), not a constant
const mapIt=glb1.find('MAP1G1_MAP');
console.log('MAP1G1_MAP present in FILE0001.GLB:', !!mapIt);
" 2>&1

